/// Draws icon `app` (1 WhatsApp, 2 Messenger, 3 Telegram) with its centre at (cx, cy), on a black background.
/// Returns false for any other app.
pub fn draw(s: &mut impl Surface, app: u8, cx: i32, cy: i32) -> bool {
    let (pal, data): (&[u16], &[u8]) = match app {
        1 => (&WHATSAPP_PAL, &WHATSAPP),
        2 => (&MESSENGER_PAL, &MESSENGER),
        3 => (&TELEGRAM_PAL, &TELEGRAM),
        _ => return false,
    };
    let (x0, mut y, mut i) = (cx - SIZE / 2, cy - SIZE / 2, 0);
    while i < data.len() {
        let n = data[i] as usize;
        i += 1;
        let mut x = x0;
        for _ in 0..n {
            let (len, p) = (data[i] as i32, data[i + 1] as usize);
            i += 2;
            if p != 0 {
                s.rect(x, y, len, 1, pal[p]);
            }
            x += len;
        }
        y += 1;
    }
    true
}
